using Finora.Domain;namespace Finora.UnitTests;public sealed class MoneyTests{[Theory][InlineData("12.34",1234)][InlineData("0.01",1)][InlineData("-4.50",-450)]public void FromMajorUnits_UsesDecimalMinorUnits(string text,long expected){var major=decimal.Parse(text,System.Globalization.CultureInfo.InvariantCulture);var money=Money.FromMajorUnits(major,"INR");Assert.Equal(expected,money.MinorUnits);Assert.Equal("INR",money.Currency);}[Fact]public void FromMajorUnits_RoundsAwayFromZeroAtMinorBoundary(){Assert.Equal(101,Money.FromMajorUnits(1.005m,"INR").MinorUnits);Assert.Equal(-101,Money.FromMajorUnits(-1.005m,"INR").MinorUnits);}}
